/// Optimized by FabriceNeyret2: https://www.shadertoy.com/user/FabriceNeyret2 ////


void mainImage( out vec4 O, vec2 u )
{
    vec2  p = 8.*u/iResolution.xy;
    float t = iTime * .5;
    p.x += t;

    for(int i; i++ < 5; )
        p.y += sin(p.x + t) * .5,
        p.x += cos(p.y + t) * .5;

    O = .5 + .5 * cos(iTime + p.xyxx + vec4(0,2,4,0));
}
